import hashlib
import threading
import time

class BackgroundWorker:
    def __init__(self):
        self.is_completed = False
        self.done_event = threading.Event()

    def run(self) -> None:
        for i in range(8):
            _ = hashlib.sha256(f"job_{i}".encode()).digest()
            time.sleep(0.001)
        self.is_completed = True
        self.done_event.set()

    def wait_for_completion(self, timeout: float = 5.0) -> bool:
        return self.done_event.wait(timeout=timeout)

def test_job_finishes():
    worker = BackgroundWorker()
    t = threading.Thread(target=worker.run)
    t.start()
    # Deterministic synchronization: wait for the worker to signal completion
    assert worker.wait_for_completion(timeout=5.0), "Background worker timed out before completion"
    assert worker.is_completed is True
    t.join(timeout=1.0)
